import os,sys,pathlib,json,time,statistics,traceback
sys.path.insert(0,'/media/IntelSSD/fireprot')
import torch
from torch.utils.cpp_extension import load
from benchmarks.atlasfold.profile_inference import resolve_physical_device,_GpuProcessMonitor
from atlasfold.model.network.primitives.triangle_update import TriangleMultiplicationOutgoing,TriangleMultiplicationIncoming
torch.set_num_threads(8);torch.manual_seed(1087);torch.cuda.init();device=resolve_physical_device();monitor=_GpuProcessMonitor(device['gpu'],os.getpid(),1);monitor.start()
build=pathlib.Path('/media/IntelSSD/fireprot/runtime/atlas_transpose_probe');build.mkdir(parents=True,exist_ok=True)
ext=load(name='atlas_transpose_probe',sources=['/tmp/fireprot_atlas_transpose_probe.cu'],build_directory=str(build),extra_cuda_cflags=['-O3'],verbose=True)
state=torch.load('/media/PM982/engramfold/folding_e2e_20260921/weights/atlasfold/snapshot/weights/atlasfold-260703.pth',map_location='cpu',weights_only=True,mmap=True)
def candidate(m,z,mask,pack_output):
 z=m.layernorm_in(z);z=z*mask.unsqueeze(-1)
 projections=m.linear_g_in(z).sigmoid()*m.linear_in(z)
 n=z.shape[-2]
 packed=ext.transpose_bf16(projections.reshape(n*n,256)).reshape(1,256,n,n)
 a,b=packed.chunk(2,dim=1)
 g=m.linear_g_out(z).sigmoid()
 product=a@b.mT if isinstance(m,TriangleMultiplicationOutgoing) else a.mT@b
 if pack_output:product=ext.transpose_bf16(product.reshape(128,n*n)).reshape(1,n,n,128)
 else:product=product.movedim(-3,-1)
 return g*m.linear_out(m.layernorm_out(product))
def bench(fn):
 samples=[]
 for i in range(5):
  a=torch.cuda.Event(enable_timing=True);b=torch.cuda.Event(enable_timing=True);a.record();y=fn();b.record();b.synchronize()
  if i>0:samples.append(a.elapsed_time(b))
 return y,statistics.median(samples)
records=[]
with torch.inference_mode(),torch.autocast('cuda',dtype=torch.bfloat16):
 for n,validn in [(1024,1000),(1536,1536)]:
  for cls,label in [(TriangleMultiplicationOutgoing,'tri_mul_out'),(TriangleMultiplicationIncoming,'tri_mul_in')]:
   m=cls(128).eval().cuda().bfloat16();prefix='main_stack.blocks.0.'+label+'.'
   m.load_state_dict({k[len(prefix):]:v for k,v in state.items() if k.startswith(prefix)},strict=True)
   x=torch.randn(1,n,n,128,device='cuda',dtype=torch.bfloat16);valid=torch.arange(n,device='cuda')<validn;mask=(valid[:,None]&valid[None,:])[None]
   reference,ms=bench(lambda:m(x,mask,'torch'))
   for output in (False,True):
    y,t=bench(lambda:candidate(m,x,mask,output));delta=y.float()-reference.float()
    r={'length':n,'valid':validn,'module':label,'pack_output':output,'native_ms':ms,'candidate_ms':t,'equal':torch.equal(y,reference),'max_abs_delta':delta.abs().max().item()}
    records.append(r);print(json.dumps(r),flush=True)
report={'device':device,'records':records,'isolation':monitor.stop()}
pathlib.Path('/media/IntelSSD/fireprot/outputs/atlasfold/triangle-multiplication-packed-probe.json').write_text(json.dumps(report,indent=2))

